@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ============================================================
   View Transitions
   ============================================================ */

/* Prevent the default cross-fade blending artefact on the root */
::view-transition-image-pair(root) {
  isolation: isolate;
}

/* --- Directional page slides -------------------------------- */

/* Base props shared by both old and new root captures when a
   direction has been set (forward or backward). */
html[data-nav-direction]::view-transition-old(root),
html[data-nav-direction]::view-transition-new(root) {
  animation-duration: 0.32s;
  animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
  animation-fill-mode: both;
}

/* Forward (grid → detail): old slides left, new enters from right */
html[data-nav-direction='forward']::view-transition-old(root) {
  animation-name: page-slide-out-left;
}
html[data-nav-direction='forward']::view-transition-new(root) {
  animation-name: page-slide-in-right;
}

/* Backward (detail → grid): old slides right, new enters from left */
html[data-nav-direction='backward']::view-transition-old(root) {
  animation-name: page-slide-out-right;
}
html[data-nav-direction='backward']::view-transition-new(root) {
  animation-name: page-slide-in-left;
}

@keyframes page-slide-out-left {
  to {
    opacity: 0;
    transform: translateX(-24%);
  }
}
@keyframes page-slide-in-right {
  from {
    opacity: 0;
    transform: translateX(24%);
  }
}
@keyframes page-slide-out-right {
  to {
    opacity: 0;
    transform: translateX(24%);
  }
}
@keyframes page-slide-in-left {
  from {
    opacity: 0;
    transform: translateX(-24%);
  }
}

/* --- Shared element: product image morphs between pages ----- */

/* The view-transition-name is set as an inline style on the
   .product-image thumbnail and the .product-hero, both keyed to
   the product slug. The browser handles the geometry interpolation
   automatically; we just tune the duration to match page slides. */
::view-transition-group(product-image) {
  animation-duration: 0.32s;
  animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
}

/* --- Skeleton → content transition -------------------------- */

/* When <ProductDetails> mounts (Suspense resolves), fade + lift in.
   @starting-style provides the "before first paint" values that
   the browser transitions FROM, giving a smooth skeleton hand-off. */
.product-info {
  transition:
    opacity 0.35s ease,
    transform 0.35s ease;
}

@starting-style {
  .product-info {
    opacity: 0;
    transform: translateY(10px);
  }
}

/* --- Respect prefers-reduced-motion ------------------------- */

@media (prefers-reduced-motion: reduce) {
  /* Make all view-transition animations near-instant */
  ::view-transition-group(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation-duration: 0.01s !important;
    animation-delay: 0s !important;
  }

  /* Also collapse the skeleton→content transition */
  .product-info {
    transition-duration: 0.01s;
    transition-delay: 0s;
  }

  @starting-style {
    .product-info {
      opacity: 0;
      transform: none;
    }
  }
}

